#!/usr/bin/env bash
# Assemble the final film: rendered 4K frames + mixed soundtrack + English subtitles.
#   build/encode.sh <frames_dir> <mix_wav> <out_dir>
# Produces:
#   transpiration_stream_4k.mp4        H.264 High, 3840x2160, 30 fps, burned-in English subtitles
#                                      plus a selectable (soft) English subtitle track, AAC 48 kHz stereo
#   transpiration_stream.en.srt        sidecar subtitles (generated by build/subtitles.py)
set -euo pipefail
FRAMES=${1:?frames dir}; MIX=${2:?mix wav}; OUT=${3:?out dir}
ROOT=$(cd "$(dirname "$0")/.." && pwd)
FPS=$(python3 -c "import json;print(json.load(open('$ROOT/timeline.json'))['fps'])")
VBITRATE=${VBITRATE:-10200k}
mkdir -p "$OUT"
cd "$ROOT"
VF="subtitles=output/transpiration_stream.en.ass:fontsdir=assets/fonts,format=yuv420p"
X264="-c:v libx264 -preset slow -profile:v high -level:v 5.1 -b:v $VBITRATE -maxrate 16M -bufsize 24M -g 60 -bf 3 \
  -x264-params aq-mode=3:aq-strength=0.9:psy-rd=1.0,0.15:deblock=-1,-1 -colorspace bt709 -color_primaries bt709 -color_trc bt709 -color_range tv"
PASSLOG="$OUT/x264pass"
ffmpeg -hide_banner -y -framerate "$FPS" -i "$FRAMES/f%05d.jpg" -vf "$VF" $X264 -pass 1 -passlogfile "$PASSLOG" -an -f mp4 /dev/null
ffmpeg -hide_banner -y -framerate "$FPS" -i "$FRAMES/f%05d.jpg" -i "$MIX" -i output/transpiration_stream.en.srt \
  -map 0:v -map 1:a -map 2:s -vf "$VF" $X264 -pass 2 -passlogfile "$PASSLOG" \
  -c:a aac -b:a 256k -ar 48000 -c:s mov_text -metadata:s:s:0 language=eng -metadata:s:a:0 language=eng \
  -disposition:s:0 0 -shortest -movflags +faststart \
  -metadata title="The Transpiration Stream — From Soil to Atmosphere" \
  "$OUT/transpiration_stream_4k.mp4"
rm -f "$PASSLOG"*
ls -la "$OUT/transpiration_stream_4k.mp4"
